-- READ-ONLY aggregate; exact-key source rows absent from reconstruction. UTC fixed bounds.
WITH c AS (SELECT CASE WHEN o.dateTime < 1293840000 THEN 2010 ELSE 2011 END AS utc_year, o.usUnits AS ou, w.usUnits AS wu, o.interval AS oi, w.interval AS wi, o.`leafTemp1` AS old_leafTemp1, w.`leafTemp1` AS wh_leafTemp1, o.`leafTemp2` AS old_leafTemp2, w.`leafTemp2` AS wh_leafTemp2, o.`leafWet1` AS old_leafWet1, w.`leafWet1` AS wh_leafWet1, o.`leafWet2` AS old_leafWet2, w.`leafWet2` AS wh_leafWet2, o.`outHumidity` AS old_outHumidity, w.`outHumidity` AS wh_outHumidity, o.`outTemp` AS old_outTemp, w.`outTemp` AS wh_outTemp, o.`outTempBatteryStatus` AS old_outTempBatteryStatus, w.`outTempBatteryStatus` AS wh_outTempBatteryStatus, o.`pressure` AS old_pressure, w.`pressure` AS wh_pressure, o.`radiation` AS old_radiation, w.`radiation` AS wh_radiation, o.`rain` AS old_rain, w.`rain` AS wh_rain
FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime
WHERE o.dateTime >= 1262304000 AND o.dateTime < 1325376000 AND r.dateTime IS NULL)
SELECT utc_year, 'leafTemp1' AS field_name, COUNT(*) AS source_only_rows, SUM(old_leafTemp1 IS NOT NULL) AS old_nonnull, SUM(wh_leafTemp1 IS NOT NULL) AS wh_nonnull, SUM(old_leafTemp1 IS NOT NULL AND wh_leafTemp1 IS NOT NULL AND old_leafTemp1 <=> wh_leafTemp1) AS paired_equal, SUM(old_leafTemp1 IS NOT NULL AND wh_leafTemp1 IS NOT NULL AND NOT(old_leafTemp1 <=> wh_leafTemp1)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'leafTemp2' AS field_name, COUNT(*) AS source_only_rows, SUM(old_leafTemp2 IS NOT NULL) AS old_nonnull, SUM(wh_leafTemp2 IS NOT NULL) AS wh_nonnull, SUM(old_leafTemp2 IS NOT NULL AND wh_leafTemp2 IS NOT NULL AND old_leafTemp2 <=> wh_leafTemp2) AS paired_equal, SUM(old_leafTemp2 IS NOT NULL AND wh_leafTemp2 IS NOT NULL AND NOT(old_leafTemp2 <=> wh_leafTemp2)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'leafWet1' AS field_name, COUNT(*) AS source_only_rows, SUM(old_leafWet1 IS NOT NULL) AS old_nonnull, SUM(wh_leafWet1 IS NOT NULL) AS wh_nonnull, SUM(old_leafWet1 IS NOT NULL AND wh_leafWet1 IS NOT NULL AND old_leafWet1 <=> wh_leafWet1) AS paired_equal, SUM(old_leafWet1 IS NOT NULL AND wh_leafWet1 IS NOT NULL AND NOT(old_leafWet1 <=> wh_leafWet1)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'leafWet2' AS field_name, COUNT(*) AS source_only_rows, SUM(old_leafWet2 IS NOT NULL) AS old_nonnull, SUM(wh_leafWet2 IS NOT NULL) AS wh_nonnull, SUM(old_leafWet2 IS NOT NULL AND wh_leafWet2 IS NOT NULL AND old_leafWet2 <=> wh_leafWet2) AS paired_equal, SUM(old_leafWet2 IS NOT NULL AND wh_leafWet2 IS NOT NULL AND NOT(old_leafWet2 <=> wh_leafWet2)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'outHumidity' AS field_name, COUNT(*) AS source_only_rows, SUM(old_outHumidity IS NOT NULL) AS old_nonnull, SUM(wh_outHumidity IS NOT NULL) AS wh_nonnull, SUM(old_outHumidity IS NOT NULL AND wh_outHumidity IS NOT NULL AND old_outHumidity <=> wh_outHumidity) AS paired_equal, SUM(old_outHumidity IS NOT NULL AND wh_outHumidity IS NOT NULL AND NOT(old_outHumidity <=> wh_outHumidity)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'outTemp' AS field_name, COUNT(*) AS source_only_rows, SUM(old_outTemp IS NOT NULL) AS old_nonnull, SUM(wh_outTemp IS NOT NULL) AS wh_nonnull, SUM(old_outTemp IS NOT NULL AND wh_outTemp IS NOT NULL AND old_outTemp <=> wh_outTemp) AS paired_equal, SUM(old_outTemp IS NOT NULL AND wh_outTemp IS NOT NULL AND NOT(old_outTemp <=> wh_outTemp)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'outTempBatteryStatus' AS field_name, COUNT(*) AS source_only_rows, SUM(old_outTempBatteryStatus IS NOT NULL) AS old_nonnull, SUM(wh_outTempBatteryStatus IS NOT NULL) AS wh_nonnull, SUM(old_outTempBatteryStatus IS NOT NULL AND wh_outTempBatteryStatus IS NOT NULL AND old_outTempBatteryStatus <=> wh_outTempBatteryStatus) AS paired_equal, SUM(old_outTempBatteryStatus IS NOT NULL AND wh_outTempBatteryStatus IS NOT NULL AND NOT(old_outTempBatteryStatus <=> wh_outTempBatteryStatus)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'pressure' AS field_name, COUNT(*) AS source_only_rows, SUM(old_pressure IS NOT NULL) AS old_nonnull, SUM(wh_pressure IS NOT NULL) AS wh_nonnull, SUM(old_pressure IS NOT NULL AND wh_pressure IS NOT NULL AND old_pressure <=> wh_pressure) AS paired_equal, SUM(old_pressure IS NOT NULL AND wh_pressure IS NOT NULL AND NOT(old_pressure <=> wh_pressure)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'radiation' AS field_name, COUNT(*) AS source_only_rows, SUM(old_radiation IS NOT NULL) AS old_nonnull, SUM(wh_radiation IS NOT NULL) AS wh_nonnull, SUM(old_radiation IS NOT NULL AND wh_radiation IS NOT NULL AND old_radiation <=> wh_radiation) AS paired_equal, SUM(old_radiation IS NOT NULL AND wh_radiation IS NOT NULL AND NOT(old_radiation <=> wh_radiation)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'rain' AS field_name, COUNT(*) AS source_only_rows, SUM(old_rain IS NOT NULL) AS old_nonnull, SUM(wh_rain IS NOT NULL) AS wh_nonnull, SUM(old_rain IS NOT NULL AND wh_rain IS NOT NULL AND old_rain <=> wh_rain) AS paired_equal, SUM(old_rain IS NOT NULL AND wh_rain IS NOT NULL AND NOT(old_rain <=> wh_rain)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year
ORDER BY utc_year, field_name;
